declare -A FIXED_HASH
FIXED_HASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2ColorTransform.java']='FA08A31B10C4801BF12C76BD2AE9371ED920CC08AD6C7A5F781BB7F9219781A2'
FIXED_HASH['app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Denoise.java']='E36C9CF5BE696A6B9F20DB1DA8585283EF72FB34D4A55D85233D3987F57DEE9B'
