FIXED_HASH['app/src/main/assets/shaders/motionv2/color_transform.glsl']='7568832F32C701D7E1F2D7F56E5B5BE7C8A8CF2B46D307478322E1824DE8AFFF'
FIXED_HASH['app/src/main/assets/shaders/motionv2/denoise.glsl']='3C4BB26080FD50DFEF4656A03F7EFC6171A1F791E77EDF0A36863AECE299720E'
FIXED_HASH['app/src/main/assets/shaders/motionv2/render.glsl']='3CFEFFAC559DE25403C49C1B3A45BDE56E8D9CA3042A74B54204E1BEC0B603D9'
FIXED_HASH['app/version.properties']='053E495F9A6C7AA301B83E3DF3BD1896307CF883E168A6384BC855210FFDD5CF'

