TARGETS=(
  "$HDRX" "$IMAGESAVER"
  "$COLORJ" "$DENOISEJ" "$RENDERJ"
  "$COLORG" "$DENOISEG" "$RENDERG"
  "$VERSION"
)

echo "=== GATE 0: EXACT 26430 + 26429 LINEAGE ==="
[[ "$(git branch --show-current)" == "$BRANCH" ]] || fail "Wrong branch"
[[ "$(git rev-parse --short=8 HEAD)" == "$EXPECTED_HEAD_SHORT" ]] || \
  fail "Expected committed 26428 HEAD $EXPECTED_HEAD_SHORT; actual $(git rev-parse --short=8 HEAD)"

# Current 26430 was intentionally built as an uncommitted working tree over 26428.
mapfile -t DIFF_FILES < <(git diff --name-only | sort)
EXPECTED_DIFF=(
  "$COLORG" "$DENOISEG" "$DACC" "$DINIT" "$RENDERG"
  "$COLORJ" "$DENOISEJ" "$RENDERJ" "$RECON" "$VERSION"
)
mapfile -t EXPECTED_DIFF_SORTED < <(printf '%s\n' "${EXPECTED_DIFF[@]}" | sort)
[[ "${#DIFF_FILES[@]}" -eq "${#EXPECTED_DIFF_SORTED[@]}" ]] || {
  printf 'Current tracked diff:\n%s\n' "${DIFF_FILES[*]}"
  fail "Unexpected tracked changes before 26431"
}
for i in "${!EXPECTED_DIFF_SORTED[@]}"; do
  [[ "${DIFF_FILES[$i]}" == "${EXPECTED_DIFF_SORTED[$i]}" ]] || {
    printf 'Current tracked diff:\n%s\n' "${DIFF_FILES[*]}"
    fail "Working tree is not exact 26430 lineage"
  }
done

for rel in "${!CURRENT[@]}"; do
  [[ -f "$rel" ]] || fail "Missing lineage file: $rel"
  [[ "$(sha "$rel")" == "${CURRENT[$rel]}" ]] || \
    fail "26430/26429 hash mismatch: $rel"
done

# These old/global files must still equal committed 26428 before we intentionally change Hdrx/ImageSaver.
git diff --quiet HEAD -- "$HDRX" || fail "Hdrx already differs from committed baseline"
git diff --quiet HEAD -- "$IMAGESAVER" || fail "ImageSaver already differs from committed baseline"
git diff --quiet HEAD -- "$RAWTOCFA" || fail "raw_to_cfa unexpectedly differs from 26428"
git diff --quiet HEAD -- "$ULTRAHDR" || fail "UltraHdrSaver unexpectedly differs from 26428"
git diff --quiet HEAD -- "$PARAMS" || fail "Parameters unexpectedly differs from 26428"

RAWTOCFA_BEFORE="$(sha "$RAWTOCFA")"
ULTRAHDR_BEFORE="$(sha "$ULTRAHDR")"
PARAMS_BEFORE="$(sha "$PARAMS")"
HDRX_BEFORE="$(sha "$HDRX")"
IMAGESAVER_BEFORE="$(sha "$IMAGESAVER")"

grep -Fq 'size = (int) (images.size() * 0.75);' "$HDRX" || fail "Legacy 75% retention anchor missing"
grep -q 'targetFraction=0.75' "$HDRX" || fail "Legacy retention telemetry anchor missing"
grep -q 'UltraHdrSaver.save' "$IMAGESAVER" || fail "Existing Photo/Night Ultra HDR path missing"
grep -q 'STATISTICS_LENS_SHADING_CORRECTION_MAP' "$PARAMS" || fail "Camera2 lens shading metadata retrieval missing"
grep -q 'exposureFusion=false esd=false ablc=false' "$POST" || fail "V2 legacy-node bypass missing"
grep -q 'initial=false autoExposure=false' "$POST" || fail "V2 Initial/AutoExposure bypass missing"
grep -q 'captureSharpening=false correctingFlow=false sharpen2=false' "$POST" || fail "V2 sharpening bypass missing"

echo "PASS: exact 26430 state and protected 26429 architecture proven"

echo "=== GATE 1: BACKUP BRANCH + BINARY PRE-EDIT PATCH ==="
SAFETY="$OUTDIR/safety_26431_allframes_body_lens_$STAMP"
CAND="$SAFETY/candidate"
ORIG="$SAFETY/originals"
mkdir -p "$CAND" "$ORIG"
BACKUP="backup/codespace-before-26431-allframes-body-lens-$STAMP"
git branch "$BACKUP"
PREPATCH="$SAFETY/pre_26431_working_tree.patch"
git diff --binary HEAD -- app > "$PREPATCH"

for rel in "${TARGETS[@]}"; do
  mkdir -p "$ORIG/$(dirname "$rel")"
  cp -a "$rel" "$ORIG/$rel"
done

PROTECTED_BEFORE="$SAFETY/protected_hashes_before.txt"
PROTECTED_AFTER="$SAFETY/protected_hashes_after.txt"
hash_protected() {
  local out="$1"
  : > "$out"
  while IFS= read -r -d '' f; do
    skip=0
    for t in "${TARGETS[@]}"; do [[ "$f" == "$t" ]] && skip=1 && break; done
    [[ "$skip" -eq 1 ]] && continue
    printf '%s  %s\n' "$(sha "$f")" "$f" >> "$out"
  done < <(git ls-files -z app)
  sort -o "$out" "$out"
}
hash_protected "$PROTECTED_BEFORE"

echo "=== GATE 2: BUILD COMPLETE TEMPORARY CANDIDATES ==="
# Copy transform-owned files to temporary copies first.
for rel in "$HDRX" "$IMAGESAVER"; do
  mkdir -p "$CAND/$(dirname "$rel")"
  cp -a "$rel" "$CAND/$rel"
done

# Decode exact fixed V2 candidates.
for rel in "${!FIXED_B64[@]}"; do
  dst="$CAND/$rel"
  mkdir -p "$(dirname "$dst")"
  printf '%s' "${FIXED_B64[$rel]}" | base64 -d > "$dst"
  [[ "$(sha "$dst")" == "${FIXED_HASH[$rel]}" ]] || fail "Fixed candidate hash mismatch: $rel"
done

TRANSFORM="$SAFETY/transform_26431_candidates.py"
printf '%s' '' | base64 -d > "$TRANSFORM"
python3 "$TRANSFORM" "$CAND/$HDRX" "$CAND/$IMAGESAVER"

CHDRX="$CAND/$HDRX"
CIMG="$CAND/$IMAGESAVER"
CCJ="$CAND/$COLORJ"
CDJ="$CAND/$DENOISEJ"
CRJ="$CAND/$RENDERJ"
CCG="$CAND/$COLORG"
CDG="$CAND/$DENOISEG"
CRG="$CAND/$RENDERG"
CV="$CAND/$VERSION"

# ----- Previous-change compatibility and ownership proof on candidates. -----
grep -q 'IRIS_26431_MOTION_V2_ALL_FRAME_HANDOFF' "$CHDRX" || fail "All-frame Motion marker missing"
grep -q 'targetFraction=1.0' "$CHDRX" || fail "Motion 100% retention telemetry missing"
grep -q 'globalGyroDiscard=false' "$CHDRX" || fail "Global discard retirement telemetry missing"
grep -q 'localConfidenceAuthority=MotionV2' "$CHDRX" || fail "V2 local confidence authority missing"
[[ "$(grep -Fc 'size = (int) (images.size() * 0.75);' "$CHDRX")" -eq 1 ]] || fail "Photo/Night legacy 75% policy was not preserved exactly once"
[[ "$(grep -c 'targetFraction=0.75' "$CHDRX")" -eq 1 ]] || fail "Photo/Night 75% telemetry not preserved"

grep -q 'IRIS_26431_MOTION_V2_NO_SYNTHETIC_BITMAP_GAINMAP' "$CHDRX" || fail "Motion synthetic gain-map bypass marker missing"
grep -q 'saveBitmapAsJPGSdrOnly' "$CHDRX" || fail "Motion SDR save route missing"
grep -q 'IRIS_26431_MOTION_V2_HONEST_SDR_JPEG' "$CIMG" || fail "ImageSaver SDR helper missing"
[[ "$(grep -c 'UltraHdrSaver.save' "$CIMG")" -eq "$(grep -c 'UltraHdrSaver.save' "$IMAGESAVER")" ]] || fail "Generic Photo/Night Ultra HDR call changed"

grep -q 'IRIS_26431_MOTION_V2_COLOR_AND_LENS_SHADING_OWNER' "$CCJ" || fail "V2 lens-shading Java owner missing"
grep -q 'LensShadingMap' "$CCJ" || fail "LensShadingMap texture binding missing"
grep -q 'sensorClipAuthorityPreLensGain=true' "$CCJ" || fail "Lens-shading clip-order telemetry missing"
grep -q 'IRIS_26431_SENSOR_CLIP_THEN_LENS_SHADING_COLOR_OWNER' "$CCG" || fail "V2 lens-shading shader owner missing"
grep -q 'vec3 sensorRelative=cameraRgb/sensorClip;' "$CCG" || fail "Sensor clip authority no longer uses unshaded RGB"
grep -Fq 'vec3 correctedCameraRgb=cameraRgb*lensRgb;' "$CCG" || fail "Lens shading correction missing"
grep -Fq 'vec3 balanced=correctedCameraRgb*sensorGains;' "$CCG" || fail "Lens shading is not before white balance"
! grep -q 'transformedLoss' "$CCG" || fail "26427 transformed overflow neutralization returned"
! grep -q 'localReliableHue' "$CCG" || fail "Neighbor hue reconstruction returned"

grep -q 'IRIS_26431_MINIMAL_SUPPORT_OWNED_RESIDUAL_CLEANUP' "$CDG" || fail "Minimal denoise shader marker missing"
grep -q 'flatLuma=mix(0.015,0.004' "$CDG" || fail "26431 luma cleanup constants missing"
grep -q 'flatChroma=mix(0.060,0.018' "$CDG" || fail "26431 chroma cleanup constants missing"
! grep -q 'uniform float noiseS' "$CDG" || fail "Generic noiseS leaked into V2 denoise"
! grep -q 'uniform float noiseO' "$CDG" || fail "Generic noiseO leaked into V2 denoise"

grep -q 'IRIS_26431_BODY_PRESERVING_HDR_TO_SDR' "$CRG" || fail "Body-preserving render marker missing"
grep -q 'const float bodyStart=0.65;' "$CRG" || fail "0.65 body identity point missing"
grep -q 'uniform float headroomStrength' "$CRG" || fail "Adaptive headroom binding missing"
grep -q 'const float logShape=3.0;' "$CRG" || fail "26431 extended-highlight shape missing"
! grep -q 'const float start=0.50' "$CRG" || fail "26430 broad 0.50 shoulder survived"
! grep -q 'logShape=6.0' "$CRG" || fail "26430 broad log shape survived"
! grep -q 'start=0.70' "$CRG" || fail "26420 0.70 shoulder survived"

grep -q '^VERSION_NAME=0\.9726431$' "$CV" || fail "Candidate version mismatch"
grep -q '^VERSION_BUILD=26431$' "$CV" || fail "Candidate build mismatch"

echo "candidate/source validation PASS"

echo "=== GATE 3: EXECUTABLE-JAVA + GLSL RUNTIME VALIDATION ==="
JAVA_VALIDATOR="$SAFETY/validate_java_ownership.py"
cat > "$JAVA_VALIDATOR" <<'PYJAVA'
from pathlib import Path
import re,sys

def executable_java(p):
    s=Path(p).read_text()
    s=re.sub(r'/\*.*?\*/',' ',s,flags=re.S)
    s=re.sub(r'//.*',' ',s)
    s=re.sub(r'"(?:\\.|[^"\\])*"','""',s)
    s=re.sub(r"'(?:\\.|[^'\\])*'","''",s)
    return s

denoise=executable_java(sys.argv[1])
for token in ('basePipeline.noiseS','basePipeline.noiseO','.noiseRstr'):
    if token in denoise:
        raise SystemExit('FAIL: executable V2 denoise consumes old Photon noise state: '+token)

color=executable_java(sys.argv[2])
for token in ('motionV2ColorGains','motionV2ColorTransform','motionCanonicalExposureGain','gainMap','mapSize'):
    if token not in color:
        raise SystemExit('FAIL: V2 color owner missing executable dependency: '+token)

render=executable_java(sys.argv[3])
for token in ('motionCanonicalExposureGain','headroomStrength','sceneWhite'):
    if token not in render:
        raise SystemExit('FAIL: V2 render owner missing executable dependency: '+token)

print('JAVA OWNERSHIP VALIDATION PASS')
PYJAVA
python3 "$JAVA_VALIDATOR" "$CDJ" "$CCJ" "$CRJ"

GLSL_VALIDATOR="$SAFETY/validate_glsl_lexical.py"
cat > "$GLSL_VALIDATOR" <<'PYGLSL'
from pathlib import Path
import re,sys

def strip_comments(s):
    s=re.sub(r'/\*.*?\*/',' ',s,flags=re.S)
    s=re.sub(r'//.*',' ',s)
    return s

for name in sys.argv[1:]:
    p=Path(name)
    text=p.read_text()
    code=strip_comments(text)
    if re.search(r'(?m)^\s*#version\b',text):
        raise SystemExit('FAIL: asset owns #version: '+str(p))
    tokens=set(re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b',code))
    if 'coherent' in tokens:
        raise SystemExit('FAIL: known GLSL reserved runtime token coherent in '+str(p))

render=strip_comments(Path(sys.argv[-1]).read_text()).replace(' ','')
for stale in ('start=0.70','start=0.50','logShape=6.0'):
    if stale in render:
        raise SystemExit('FAIL: stale render behavior survived: '+stale)
print('LEXICAL GLSL VALIDATION PASS')
PYGLSL
python3 "$GLSL_VALIDATOR" "$CCG" "$CDG" "$CRG"

if ! command -v glslangValidator >/dev/null 2>&1; then
  echo "glslangValidator missing; installing before real source is touched..."
  command -v sudo >/dev/null 2>&1 || fail "glslangValidator required and sudo unavailable"
  sudo apt-get update
  sudo apt-get install -y glslang-tools
fi
command -v glslangValidator >/dev/null 2>&1 || fail "glslangValidator unavailable"

FRAG_WRAP="$SAFETY/make_fragment_wrapper.py"
cat > "$FRAG_WRAP" <<'PYFRAG'
from pathlib import Path
import sys
Path(sys.argv[2]).write_text('#version 310 es\n'+Path(sys.argv[1]).read_text())
PYFRAG

for spec in "color:$CCG" "denoise:$CDG" "render:$CRG"; do
  n="${spec%%:*}"; src="${spec#*:}"; wrap="$SAFETY/${n}_26431.frag"
  python3 "$FRAG_WRAP" "$src" "$wrap"
  glslangValidator -S frag "$wrap" > "$SAFETY/glslang_${n}.txt" 2>&1 || { cat "$SAFETY/glslang_${n}.txt"; fail "GLSL compile failed: $n"; }
  cat "$SAFETY/glslang_${n}.txt"
done

# Recompile the unchanged 26429 direct reconstruction shaders too.
COMP_WRAP="$SAFETY/make_compute_wrapper.py"
cat > "$COMP_WRAP" <<'PYCOMP'
from pathlib import Path
import re,sys
src=Path(sys.argv[1]).read_text()
src=re.sub(r'(?m)^#define\s+LAYOUT\s+//\s*\nLAYOUT\s*\n','',src,count=1)
Path(sys.argv[2]).write_text('#version 310 es\nlayout(local_size_x=8, local_size_y=8, local_size_z=1) in;\n'+src)
PYCOMP
for spec in "direct_init:$DINIT" "direct_acc:$DACC"; do
  n="${spec%%:*}"; src="${spec#*:}"; wrap="$SAFETY/${n}_26429.comp"
  python3 "$COMP_WRAP" "$src" "$wrap"
  glslangValidator -S comp "$wrap" > "$SAFETY/glslang_${n}.txt" 2>&1 || { cat "$SAFETY/glslang_${n}.txt"; fail "Preserved 26429 shader compile failed: $n"; }
  cat "$SAFETY/glslang_${n}.txt"
done

echo "GLSL COMPILER VALIDATION PASS"
echo "Temporary-copy validation: PASS"

echo "=== GATE 4: APPLY EXACT VALIDATED CANDIDATES ==="
for rel in "${TARGETS[@]}"; do
  cp "$CAND/$rel" "$rel"
done

echo "=== GATE 5: PRE-BUILD SAFETY / PRIOR-CHANGE NON-NEGATION PROOF ==="
# Exact source equality with the already validated temporary candidate.
for rel in "${TARGETS[@]}"; do
  [[ "$(sha "$rel")" == "$(sha "$CAND/$rel")" ]] || fail "Applied source differs from validated candidate: $rel"
done

hash_protected "$PROTECTED_AFTER"
cmp -s "$PROTECTED_BEFORE" "$PROTECTED_AFTER" || fail "A protected tracked app file changed"

# Explicitly prove the fixes we are NOT replacing remain byte-identical.
[[ "$(sha "$RECON")" == "${CURRENT[$RECON]}" ]] || fail "26429 reconstruction changed"
[[ "$(sha "$DINIT")" == "${CURRENT[$DINIT]}" ]] || fail "26429 direct initializer changed"
[[ "$(sha "$DACC")" == "${CURRENT[$DACC]}" ]] || fail "26429 direct accumulator changed"
[[ "$(sha "$ALIGN")" == "${CURRENT[$ALIGN]}" ]] || fail "MotionV2Alignment changed"
[[ "$(sha "$POST")" == "${CURRENT[$POST]}" ]] || fail "V2-isolated PostPipeline changed"
[[ "$(sha "$INPUT")" == "${CURRENT[$INPUT]}" ]] || fail "MotionV2CfaInput changed"
[[ "$(sha "$RAWTOCFA")" == "$RAWTOCFA_BEFORE" ]] || fail "raw_to_cfa changed; 26429 sensor-domain contract was not preserved"
[[ "$(sha "$ULTRAHDR")" == "$ULTRAHDR_BEFORE" ]] || fail "Generic UltraHdrSaver source changed"
[[ "$(sha "$PARAMS")" == "$PARAMS_BEFORE" ]] || fail "Parameters metadata authority changed"

# Hdrx/ImageSaver must be the only newly introduced cross-boundary ownership edits.
[[ "$HDRX_BEFORE" != "$(sha "$HDRX")" ]] || fail "Hdrx did not change"
[[ "$IMAGESAVER_BEFORE" != "$(sha "$IMAGESAVER")" ]] || fail "ImageSaver did not change"

# Re-run executable and shader validations on REAL source.
python3 "$JAVA_VALIDATOR" "$DENOISEJ" "$COLORJ" "$RENDERJ"
python3 "$GLSL_VALIDATOR" "$COLORG" "$DENOISEG" "$RENDERG"

grep -q 'targetFraction=1.0' "$HDRX" || fail "Motion all-frame routing missing after apply"
[[ "$(grep -c 'targetFraction=0.75' "$HDRX")" -eq 1 ]] || fail "Non-Motion retention changed after apply"
grep -q 'saveBitmapAsJPGSdrOnly' "$HDRX" || fail "Motion SDR routing missing after apply"
[[ "$(grep -c 'UltraHdrSaver.save' "$IMAGESAVER")" -eq "$(grep -c 'UltraHdrSaver.save' "$ORIG/$IMAGESAVER")" ]] || fail "Generic Ultra HDR path changed after apply"

git diff --check -- "${TARGETS[@]}"

echo "candidate/source validation PASS"
echo "Temporary-copy validation: PASS"
echo "PRE-BUILD SAFETY PROOF PASSED"

POSTPATCH="$SAFETY/post_26431_working_tree.patch"
git diff --binary HEAD -- app > "$POSTPATCH"

echo "=== GATE 6: BUILD $NEW_VERSION / $NEW_BUILD ==="
chmod +x ./gradlew
BUILDLOG="$OUTDIR/build_26431_allframes_body_lens_$STAMP.txt"
set +e
./gradlew :app:assembleDebug --stacktrace 2>&1 | tee "$BUILDLOG"
RC=${PIPESTATUS[0]}
set -e
[[ "$RC" -eq 0 ]] || fail "Gradle failed rc=$RC; see $BUILDLOG"
grep -q 'BUILD SUCCESSFUL' "$BUILDLOG" || fail "BUILD SUCCESSFUL not found"

APK_SRC="$(find app/build/outputs/apk -type f -name '*.apk' -printf '%T@ %p\n' | sort -nr | head -1 | cut -d' ' -f2-)"
[[ -n "$APK_SRC" && -f "$APK_SRC" ]] || fail "Built APK not found"
APK_NAME="IrisCamera-0.9726431-26431-v2-allframes-body-lens-ownership-debug.apk"
APK_ROOT="$SRC/$APK_NAME"

# Keep exactly one user APK: move, do not copy. Only after successful build.
find "$SRC" -maxdepth 1 -type f -name 'IrisCamera-*.apk' ! -name "$APK_NAME" -delete
mv -f "$APK_SRC" "$APK_ROOT"
find app/build -type f -name '*.apk' -delete
[[ -f "$APK_ROOT" ]] || fail "Final root APK missing"
[[ "$(find "$SRC" -type f -name '*.apk' 2>/dev/null | wc -l)" -eq 1 ]] || fail "More than one APK remains"

RESULT="$OUTDIR/26431_ALLFRAMES_BODY_LENS_OWNERSHIP_RESULT_$STAMP.txt"
cat > "$RESULT" <<EOF
26431 MOTION V2 ALL-FRAME / BODY-CONTRAST / LENS OWNERSHIP
Timestamp: $(date --iso-8601=seconds)
Branch: $BRANCH
Committed base HEAD: $(git rev-parse HEAD)
Version/build: $NEW_VERSION / $NEW_BUILD

IMPLEMENTED:
- Motion V2 bypasses old Hdrx 75% global gyro frame discard; all captured frames reach V2.
- Photo/Night legacy 75% retention behavior remains present.
- 26429 reconstruction, alignment, direct init/accum, direct input and isolated PostPipeline are byte-identical.
- 26431 render preserves linear scene body through 0.65 and uses adaptive Hermite + >1 highlight allocation.
- 26430 broad 0.50 log shoulder and old 0.70 shoulder are absent.
- residual 3x3 denoise reduced to minimal support-owned cleanup; no Photon noiseS/noiseO/noiseRstr.
- Camera2 lens-shading map is owned by MotionV2ColorTransform after sensor-clip authority and before WB/matrix.
- Motion no longer uses legacy synthetic bitmap-derived Ultra HDR gain map; it saves honest SDR JPEG.
- Photo/Night generic Ultra HDR saver remains unchanged.
- no sharpening and no local tone stage added.

SAFETY:
- Backup branch: $BACKUP
- Pre-edit binary patch: $PREPATCH
- Post-edit binary patch: $POSTPATCH
- GLSL compiler validation PASS before source modification.
- candidate/source validation PASS
- Temporary-copy validation: PASS
- PRE-BUILD SAFETY PROOF PASSED
- BUILD SUCCESSFUL verified

APK (single copy): $APK_ROOT
Build log: $BUILDLOG
Safety folder: $SAFETY

No commit.
No push.
dev untouched.
EOF

# Current-build housekeeping: keep root clean and outputs current-only.
CURRENT_SCRIPT="$(basename "$0")"
find "$SRC" -maxdepth 1 -type f -name 'build_*.sh' ! -name "$CURRENT_SCRIPT" -print0 |
while IFS= read -r -d '' old; do
  rel="${old#$SRC/}"
  if ! git ls-files --error-unmatch -- "$rel" >/dev/null 2>&1; then
    rm -f -- "$old"
  fi
done
find "$OUTDIR" -mindepth 1 -maxdepth 1 ! -name '*26431*' -print0 |
while IFS= read -r -d '' old; do rm -rf -- "$old"; done

echo "======================================================================"
echo "BUILD SUCCESSFUL VERIFIED"
echo "APK: $APK_ROOT"
echo "RESULT: $RESULT"
echo "SAFETY: $SAFETY"
echo "Exactly one APK remains. No commit. No push. dev untouched."
echo "======================================================================"
